# situ capability map v1
# schema: pcap.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.
#
# A struct's size is a bare number where it is fixed, `min..max` where
# it is bounded, and `min..` where nothing bounds it.

struct pcap size=24.. access=Sequential mutate=Shifting repr=ConditionallyConverted(magic) atomic=NonAtomic canonical=CanonicalGiven(magic)
  pcap.magic                             offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  pcap.version_major                     offset=AbsoluteStatic(0x04) size=Fixed(2) align=Aligned(4) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.version_minor                     offset=AbsoluteStatic(0x06) size=Fixed(2) align=Aligned(2) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.thiszone                          offset=AbsoluteStatic(0x08) size=Fixed(4) align=Aligned(8) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.sigfigs                           offset=AbsoluteStatic(0x0C) size=Fixed(4) align=Aligned(4) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.snaplen                           offset=AbsoluteStatic(0x10) size=Fixed(4) align=Aligned(8) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.network                           offset=AbsoluteStatic(0x14) size=Fixed(4) align=Aligned(4) repr=ConditionallyConverted(magic) atomic=AtomicWord canonical=CanonicalGiven(magic)
  pcap.packets                           offset=AbsoluteStatic(0x18) size=Unbounded align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic access=Sequential mutate=Shifting
  pcap.packets[]                         offset=FrameStatic(0x00) size=Bounded(16, 4294967311) align=Aligned(8) repr=ConditionallyConverted(order) atomic=NonAtomic access=Sequential mutate=Shifting canonical=CanonicalGiven(order)
  pcap.packets[].order                   parameter
  pcap.packets[].ts_sec                  offset=FrameStatic(0x00) size=Fixed(4) align=Aligned(8) repr=ConditionallyConverted(order) atomic=AtomicWord canonical=CanonicalGiven(order)
  pcap.packets[].ts_usec                 offset=FrameStatic(0x04) size=Fixed(4) align=Aligned(4) repr=ConditionallyConverted(order) atomic=AtomicWord canonical=CanonicalGiven(order)
  pcap.packets[].incl_len                offset=FrameStatic(0x08) size=Fixed(4) align=Aligned(8) repr=ConditionallyConverted(order) atomic=AtomicWord canonical=CanonicalGiven(order)
  pcap.packets[].orig_len                offset=FrameStatic(0x0C) size=Fixed(4) align=Aligned(4) repr=ConditionallyConverted(order) atomic=AtomicWord canonical=CanonicalGiven(order)
  pcap.packets[].data                    offset=FrameStatic(0x10) size=Bounded(0, 4294967295) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting

